import { findCommentSpans } from "../findCommentSpans/index.js";
/**
 * Finds the spans of a string's inline comments: {@link findCommentSpans} without the block ones, as {@link rewriteInlineComments} spells them. A rule asking whether a value node stands in a comment asks {@link findCommentSpanHolding} instead, since the value parser closes a block comment early.
 * @param text - The string.
 * @param reading - What the node's syntax makes of a `//` comment.
 * @returns The spans, in the string's coordinates.
 */
export function findInlineCommentSpans(text, reading) {
    return findCommentSpans(text, reading)
        .filter(({ isInline }) => isInline)
        .map(({ start, end }) => ({ start, end }));
}
